div.script:
document.addEventListener("DOMContentLoaded", function() {
    // Xử lý ẩn/hiện mật khẩu ở trang login
    const pwdInput = document.getElementById('password');
    if (pwdInput && !pwdInput.closest('.input-group')) {
        const parent = pwdInput.parentElement;
        const wrapper = document.createElement('div');
        wrapper.className = 'input-group mb-3';
        parent.insertBefore(wrapper, pwdInput);
        wrapper.appendChild(pwdInput);

        const toggleBtn = document.createElement('button');
        toggleBtn.type = 'button';
        toggleBtn.className = 'btn btn-light border text-secondary px-3';
        toggleBtn.style.cssText = 'border-color: #dee2e6 !important; background-color: #f8f9fa; z-index: 5; border-top-right-radius: 0.5rem !important; border-bottom-right-radius: 0.5rem !important;';
        toggleBtn.innerHTML = '';
        toggleBtn.onclick = function() {
            const icon = document.getElementById('toggle-password-icon');
            if (pwdInput.type === 'password') {
                pwdInput.type = 'text';
                icon.classList.remove('bi-eye');
                icon.classList.add('bi-eye-slash');
            } else {
                pwdInput.type = 'password';
                icon.classList.remove('bi-eye-slash');
                icon.classList.add('bi-eye');
            }
        };
        wrapper.appendChild(toggleBtn);
    }

    // Đảm bảo quét ẩn logo và nút Manage databases nếu load bằng selector
    const logos = document.querySelectorAll('img[src*="logo"], img.img-fluid');
    logos.forEach(img => {
        img.style.setProperty('display', 'none', 'important');
    });

    const manageLinks = document.querySelectorAll('a[href*="/web/database/manager"]');
    manageLinks.forEach(link => {
        const container = link.closest('.text-center') || link;
        container.style.setProperty('display', 'none', 'important');
    });
});
